"use client";

import React, { useState } from "react";
import { ShoppingCart, Plus } from "lucide-react";

export function ProductCardCompact() {
  const [added, setAdded] = useState(false);

  return (
    <div className="w-full max-w-xs bg-card/45 backdrop-blur-xl border border-border/50 rounded-2xl shadow-xl select-none font-sans overflow-hidden text-foreground">
      <div className="p-4 relative">
        <div className="h-28 bg-secondary/20 rounded-xl border border-white/[0.04] mb-3 flex items-center justify-center">
          <ShoppingCart className="w-8 h-8 text-violet-400" />
        </div>

        <div className="space-y-1">
          <h4 className="text-xs font-black">Compact Core Package</h4>
          <div className="flex justify-between items-center mt-2">
            <span className="text-xs font-black">$49.00</span>
            <button 
              onClick={() => setAdded(!added)}
              className={`p-1.5 rounded-lg border transition-all ${
                added ? "bg-emerald-600 border-transparent text-white" : "bg-secondary border-border text-foreground"
              }`}
            >
              <Plus className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
